onClick:
{{
  !inpEmployeeCode.text ||
  !inpFullName.text ||
  !inpEmployeeEmail.text ||
  !selEmployeeRole.selectedOptionValue ||
  !inpDepartment.text ||
  !inpDesignation.text ||
  !dpJoiningDate.selectedDate
    ? showAlert("Please complete all required fields.", "warning")
    : (
        selEmployeeRole.selectedOptionLabel === "Employee" &&
        !selReportingManager.selectedOptionValue
      )
      ? showAlert("Please select a reporting manager.", "warning")
      : q_hr_add_employee.run()
          .then(() => {
            showAlert("Employee added successfully.", "success");

            resetWidget("inpEmployeeCode");
            resetWidget("inpFullName");
            resetWidget("inpEmployeeEmail");
            resetWidget("selEmployeeRole");
            resetWidget("inpDepartment");
            resetWidget("inpDesignation");
            resetWidget("selReportingManager");
            resetWidget("dpJoiningDate");

            return Promise.all([
              q_hr_get_employees.run(),
              q_hr_get_managers.run()
            ]);
          })
          .catch((error) => {
            showAlert(
              error.message || "Unable to add employee.",
              "error"
            );
          })
}}
